<?php require_once __DIR__ . '/../includes/auth.php'; requireHOD(); $p=db(); $d=$_SESSION['user']['department_id']; $counts=[]; foreach(['batches'=>'Total Batches','students'=>'Total Students','subjects'=>'Total Subjects'] as $table=>$label){$q=$p->prepare("SELECT COUNT(*) FROM $table ".($table==='students'?'s JOIN batches b ON b.id=s.batch_id WHERE b.department_id=?':'WHERE department_id=?'));$q->execute([$d]);$counts[$label]=$q->fetchColumn();} $q=$p->prepare("SELECT COUNT(*) FROM users WHERE department_id=? AND role='lecturer'");$q->execute([$d]);$counts['Total Lecturers']=$q->fetchColumn(); $title='HOD Dashboard'; require __DIR__.'/../includes/header.php'; ?><div class="cards"><?php foreach($counts as $label=>$value): ?><div class="card"><span><?=e($label)?></span><strong><?=e((string)$value)?></strong></div><?php endforeach; ?></div><section class="panel"><h2>Department overview</h2><p>Use the navigation to create batches, maintain people and subjects, then assign subjects and lecturers through Batch Management.</p></section><?php require __DIR__.'/../includes/footer.php'; ?>
